impl Solution {
    pub fn min_stones_to_remove(colors: Vec<u8>, n: usize) -> usize {
        let mut count = 0;
        let mut i = 0;
        while i < n - 1 {
            if colors[i] == colors[i + 1] {
                count += 1;
                let mut j = i + 1;
                while j < n - 1 && colors[j] == colors[j + 1] {
                    j += 1;
                }
                i = j + 1;
            } else {
                i += 1;
            }
        }
        count
    }
}

